 for k in range(j+1,20):
  M.append(Z[:,j]*Z[:,k]);desc.append(('zz',j,k))
for j in cont:
 for k in range(20):
  if j!=k:
   M.append(Q[:,j]*Z[:,k]);desc.append(('qz',j,k))
